def fill_reflect_into(dst,r0,r1,c0,c1,tile,ar,ac,flip_up=False,flip_left=False):
 th,tw=len(tile),len(tile[0])
 for r in range(r0,r1+1):
  for c in range(c0,c1+1):
   dr=r-ar;dc=c-ac;tr=dr%th;tc=dc%tw
   if flip_up and dr<0:tr=th-1-tr
   if flip_left and dc<0:tc=tw-1-tc
   dst[r][c]=tile[tr][tc]
